package hvac_visibility_priority_supervisor.HVAC_Visibility_Priority_Supervisor

import org.sireum._
import art.Art
import hvac_visibility_priority_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait VisibilityServiceProposer_supervision_visibilityServiceProposer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer)
  }

  /** helper function to set the values of all input ports.
   * @param visibilityNeed payload for data port visibilityNeed
   * @param visibilityPath payload for data port visibilityPath
   */
  def put_concrete_inputs(visibilityNeed : HVAC_Visibility_Priority_Supervisor.VisibilityNeed.Type,
                          visibilityPath : HVAC_Visibility_Priority_Supervisor.VisibilityPathReadiness): Unit = {
    put_visibilityNeed(visibilityNeed)
    put_visibilityPath(visibilityPath)
  }


  /** helper function to check VisibilityServiceProposer_supervision_visibilityServiceProposer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param visibilityProposal method that will be called with the value of the outgoing data
   *        port 'visibilityProposal'.
   */
  def check_concrete_output(visibilityProposal: HVAC_Visibility_Priority_Supervisor.VisibilityProposal => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val visibilityProposalValue: HVAC_Visibility_Priority_Supervisor.VisibilityProposal = get_visibilityProposal().get
    if(!visibilityProposal(visibilityProposalValue)) {
      testFailures = testFailures :+ st"'visibilityProposal' did not match expected: value of the outgoing data port is ${visibilityProposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_visibilityNeed(value : HVAC_Visibility_Priority_Supervisor.VisibilityNeed.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer.operational_api.visibilityNeed_Id, HVAC_Visibility_Priority_Supervisor.VisibilityNeed_Payload(value))
  }

  // setter for in DataPort
  def put_visibilityPath(value : HVAC_Visibility_Priority_Supervisor.VisibilityPathReadiness): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer.operational_api.visibilityPath_Id, HVAC_Visibility_Priority_Supervisor.VisibilityPathReadiness_Payload(value))
  }

  // getter for out DataPort
  def get_visibilityProposal(): Option[HVAC_Visibility_Priority_Supervisor.VisibilityProposal] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.VisibilityProposal] = get_visibilityProposal_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.VisibilityProposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port visibilityProposal.  Expecting 'HVAC_Visibility_Priority_Supervisor.VisibilityProposal_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.VisibilityProposal]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_visibilityProposal_payload(): Option[HVAC_Visibility_Priority_Supervisor.VisibilityProposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_visibilityServiceProposer.initialization_api.visibilityProposal_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.VisibilityProposal_Payload]]
  }

}
